// File: edrv32_sys_case_tb.sv
// Spec: sys-subsys-testplan 3.1-3.5.
// Description: Common runnable top; manifests select the independent scenario.
// Clock domains: generated by u_env.
module edrv32_sys_case_tb #(parameter int CASE_ID = 101);
    edrv32_sys_env u_env();
    int case_id = CASE_ID;
    initial begin
        void'($value$plusargs("CASE_ID=%d", case_id));
        u_env.boot();
    end
    generate
        if (CASE_ID / 100 == 1) begin : g_xbar
            initial begin
                wait (u_env.rst_sys_n);
                u_env.wait_sys(3);
                u_env.xbar_case(case_id);
                u_env.report_coverage();
                $display("PASS sys_subsys case=%0d", case_id);
                $finish;
            end
        end
        if (CASE_ID / 100 == 2) begin : g_memory
            initial begin
                wait (u_env.rst_sys_n);
