        if (CASE_ID / 100 == 9) begin : g_sysctrl
            initial begin
                wait (u_env.rst_sys_n);
                u_env.wait_sys(3);
                u_env.sysctrl_case(case_id);
                u_env.report_coverage();
                $display("PASS sys_subsys case=%0d", case_id);
                $finish;
            end
        end
    endgenerate
    initial begin
        #200000000;
        $fatal(1, "FAIL sys_subsys watchdog time=%0t", $time);
    end
endmodule
